export fn ic_555_timer(v:[*]const i64,n:usize)f64{if(n!=4)return -1.0e300;const m=v[0];const a=v[1];const b=v[2];const c=v[3];if((m!=0 and m!=1) or a<1 or a>1000000 or b<1 or b>1000000 or (m==0 and (c<1 or c>1000000)) or (m==1 and (c<0 or c>1000000)))return -1.0e300;if(m==0)return (1.44/(@as(f64,@floatFromInt(a+2*b))*@as(f64,@floatFromInt(c))))*1e6;return (@as(f64,@floatFromInt(a+b))/@as(f64,@floatFromInt(a+2*b)))*100.0;}
